import { useEffect, useState } from "react";
import { NavLink, Outlet, useNavigate } from "react-router-dom";
import LinkioBrand from "./LinkioBrand";
import { logout as apiLogout } from "../services/accountApi";
import { clearAuth, getUserEmail } from "../services/auth";
import { syncIndividualProfileId } from "../services/applicationsApi";

const DashboardIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="flex-shrink-0">
    <rect x="3" y="3" width="7" height="9" />
    <rect x="14" y="3" width="7" height="5" />
    <rect x="14" y="12" width="7" height="9" />
    <rect x="3" y="16" width="7" height="5" />
  </svg>
);

const AnnouncementsIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="flex-shrink-0">
    <path d="M12 22c1.1 0 2-.9 2-2H10c0 1.1.9 2 2 2z" />
    <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9z" />
  </svg>
);

const ProfileIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="flex-shrink-0">
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
    <circle cx="12" cy="7" r="4" />
  </svg>
);

const SettingsIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="flex-shrink-0">
    <circle cx="12" cy="12" r="3" />
    <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
  </svg>
);

const menuItems = [
  { to: "/professional/dashboard", label: "Dashboard", icon: <DashboardIcon />, end: true },
  { to: "/professional/dashboard/announcements", label: "Announcements", icon: <AnnouncementsIcon /> },
  { to: "/professional/dashboard/profile", label: "My Profile", icon: <ProfileIcon /> },
];

const accountItems = [{ to: "/professional/dashboard/settings", label: "Settings", icon: <SettingsIcon /> }];

export default function ProfessionalDashboardLayout() {
  const navigate = useNavigate();
  const userEmail = getUserEmail();
  const initials = userEmail ? userEmail.slice(0, 2).toUpperCase() : "??";
  const [isCollapsed, setIsCollapsed] = useState(false);

  useEffect(() => {
    syncIndividualProfileId();
  }, []);

  const handleLogout = async () => {
    await apiLogout();
    clearAuth();
    navigate("/sign-in", { replace: true });
  };

  const navItem = (item) => (
    <NavLink
      key={item.to}
      to={item.to}
      end={item.end}
      title={isCollapsed ? item.label : undefined}
      className={({ isActive }) =>
        `flex items-center gap-3 px-3 py-2.5 rounded-2xl text-sm transition-all duration-300
        ${
          isActive
            ? "bg-white/15 text-white font-medium shadow-sm"
            : "text-white/60 hover:bg-white/5 hover:text-white"
        }
        ${isCollapsed ? "justify-center" : ""}`
      }
    >
      {item.icon}
      {!isCollapsed && <span>{item.label}</span>}
    </NavLink>
  );

  return (
    <div className="flex min-h-screen bg-gradient-to-tr from-[#f8fafc] via-[#f1f5f9] to-[#1b3a5c]/10 font-sans transition-all duration-300">
      {/* Collapsible Dark Navy Sidebar */}
      <aside 
        className={`bg-[#0B1E36] border-r border-[#1e293b]/20 fixed top-0 left-0 bottom-0 flex flex-col px-4 py-5 z-10 transition-all duration-300 ease-out
          ${isCollapsed ? "w-20" : "w-64"}
        `}
      >
        {/* Toggle Button */}
        <button
          type="button"
          onClick={() => setIsCollapsed(!isCollapsed)}
          className="absolute top-6 -right-3 w-6 h-6 rounded-full bg-[#1b3a5c] text-white hover:bg-[#132742] flex items-center justify-center shadow-md border border-white/20 hover:scale-105 active:scale-95 transition-all z-20 cursor-pointer text-[10px]"
        >
          {isCollapsed ? "▶" : "◀"}
        </button>

        <div className={`px-1 mb-8 flex items-center ${isCollapsed ? "justify-center" : ""}`}>
          <LinkioBrand 
            logoWidth={32} 
            logoHeight={20} 
            wordmarkClassName={isCollapsed ? "hidden" : "font-serif text-lg font-semibold text-white tracking-tight"}
          />
        </div>

        {!isCollapsed && (
          <p className="px-1 mb-2 text-[0.65rem] font-bold tracking-widest text-white/40 uppercase">Menu</p>
        )}
        <nav className="flex flex-col gap-1 mb-6">{menuItems.map(navItem)}</nav>

        {!isCollapsed && (
          <p className="px-1 mb-2 text-[0.65rem] font-bold tracking-widest text-white/40 uppercase">Account</p>
        )}
        <nav className="flex flex-col gap-1 mb-6">{accountItems.map(navItem)}</nav>

        {/* Italian Label */}
        {!isCollapsed && (
          <div className="mt-6 px-3 py-2 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex items-center gap-2 select-none animate-fade-in">
            <span className="text-xs">🇮🇹</span>
            <span className="text-[10px] font-bold tracking-wider text-emerald-400 uppercase">
              Italian Professional
            </span>
          </div>
        )}

        <div className={`mt-auto flex items-center gap-3 bg-white/5 border border-white/10 rounded-2xl p-3 mb-2 ${isCollapsed ? "justify-center" : ""}`}>
          <div className="w-9 h-9 bg-[#1b3a5c] border border-white/10 rounded-full flex items-center justify-center text-white text-xs font-semibold flex-shrink-0">
            {initials}
          </div>
          {!isCollapsed && (
            <div className="truncate">
              <p className="text-sm font-medium text-white truncate max-w-[140px]">
                {userEmail || "Professional"}
              </p>
              <p className="text-xs text-white/50">Professional</p>
            </div>
          )}
        </div>

        <button
          type="button"
          onClick={handleLogout}
          title={isCollapsed ? "Log out" : undefined}
          className={`text-left text-sm text-white/70 px-3 py-2.5 hover:text-white transition-all flex items-center gap-2 ${isCollapsed ? "justify-center" : ""}`}
        >
          <span className="text-base">←</span>
          {!isCollapsed && <span>Log out</span>}
        </button>
      </aside>

      {/* Main Content Area */}
      <div 
        className={`flex-1 flex flex-col min-h-screen transition-all duration-300 ease-out
          ${isCollapsed ? "ml-20" : "ml-64"}
        `}
      >
        <div className="p-8 flex-1">
          <Outlet />
        </div>
